<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Promo; use Illuminate\Http\Request; use Illuminate\Support\Str;
class PromoController extends Controller { public function index(){return view('admin.promos.index',['promos'=>Promo::orderBy('sort_order')->get()]);} public function create(){return view('admin.promos.form',['promo'=>new Promo]);} public function store(Request $r){$d=$this->data($r);$d['is_active']=$r->boolean('is_active');$d['image']=$this->image($r)??'';Promo::create($d);return redirect('/admin/promos')->with('ok','Promo berhasil ditambahkan.');} public function edit(Promo $promo){return view('admin.promos.form',compact('promo'));} public function update(Request $r,Promo $promo){$d=$this->data($r);$d['is_active']=$r->boolean('is_active');$i=$this->image($r);if($i)$d['image']=$i;$promo->update($d);return redirect('/admin/promos')->with('ok','Promo diperbarui.');} public function destroy(Promo $promo){$promo->delete();return back()->with('ok','Promo dihapus.');} private function data($r){return $r->validate(['eyebrow'=>'nullable','title'=>'required','text'=>'nullable','image'=>'nullable','button_text'=>'nullable','button_url'=>'nullable','is_active'=>'nullable','sort_order'=>'nullable|integer']);} private function image($r){if(!$r->hasFile('image'))return null;$f=$r->file('image');$n=Str::uuid().'.'.$f->getClientOriginalExtension();$f->move(public_path('uploads/promos'),$n);return '/uploads/promos/'.$n;} }
